mapper.select:
select b.blog_id, b.author_id, u.nick_name as author_nickname, b.title, b.summary, b.cover_url, b.publish_time, b.view_count, b.like_count, b.collect_count from blog b left join sys_user u on b.author_id = u.user_id inner join blog_tag bt on bt.blog_id = b.blog_id where and bt.tag_id in #{tid} and b.blog_id <> #{excludeBlogId}
and b.blog_id not in #{vid}
group by b.blog_id order by (b.like_count * 2 + b.collect_count * 3 + b.view_count) desc, b.publish_time desc limit #{size}

select b.blog_id, b.author_id, u.nick_name as author_nickname, b.title, b.summary, b.cover_url, b.publish_time, b.view_count, b.like_count, b.collect_count from blog b left join sys_user u on b.author_id = u.user_id where and b.blog_id <> #{excludeBlogId}
and b.blog_id not in #{eid}
order by (b.like_count * 2 + b.collect_count * 3 + b.view_count) desc, b.publish_time desc limit #{size}
